namespace sarif.export.symbols;

using ghidra.program.database.symbol;
using ghidra.program.database.symbol;
using ghidra.program.database.symbol;
using ghidra.program.model.data.ISF;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;

public class ExtSymbol : IsfObject {

	string name;
	string location;
	Boolean namespaceIsClass;
	string kind;
	string type;
	string sourceType;
	bool primary;
	bool pinned;

	public ExtSymbol(Symbol symbol) {
		name = symbol.getName();
		location = getNamespace(symbol);
		kind = checkGlobal(symbol) ? "global" : "local";
		sourceType = symbol.getSource().toString();
		primary = symbol.isPrimary();
		pinned = symbol.isPinned();
		if (symbol is ClassSymbol) {
			type = "class";
		} else if (symbol is LibrarySymbol) {
			type = "library";
		} else if (symbol is NamespaceSymbol) {
			type = "namespace";
		}
		// NB: DO NOT add type==function, as this will affect the execution order
		//if (symbol instanceof FunctionSymbol fs) {
		//	type = "function";
		//}
	}

	/**
	 * Returns the name of symbol qualified with any namespace information. For
	 * example, "User32.dll::SomeClass::printf".
	 */
	private string getNamespace(Symbol symbol) {
		StringBuffer buffer = new StringBuffer();
		Namespace @namespace = symbol.getParentNamespace();
		while (!@namespace.isGlobal()) {
			buffer.insert(0, @namespace.getName() + "::");
			if (@namespace is GhidraClass) {
				namespaceIsClass = true;
			}
			@namespace = @namespace.getParentNamespace();
		}
		return buffer.toString();
	}

	private bool checkGlobal(Symbol symbol) {
		if (symbol.isGlobal()) {
			return true;
		}
		Namespace parent = symbol.getParentNamespace();
		if (parent is Library) {
			return true;
		}
		return false;
	}

}
